   434	/****************************************************************************
   435	 * Name: bk7258_dma_get_channel_dest_addr
   436	 *
   437	 * Description:
   438	 *   The channel's destination address register.  On this DMA word 1 is not a
   439	 *   latched copy of what was programmed: the channel advances it as it
   440	 *   writes, so in REPEAT mode it is the ring's write pointer and can be read
   441	 *   at any time without disturbing the transfer.
   442	 *
   443	 *   That matters for the JPEG drain, which needs to know where one frame's
   444	 *   bitstream ends without stopping the channel -- stopping it is what loses
   445	 *   the bytes of the following frame.
   446	 *
   447	 ****************************************************************************/
