   459	/****************************************************************************
   460	 * Name: bk7258_dma_flush_src_buffer
   461	 *
   462	 * Description:
   463	 *   Pushes out whatever partial data-width unit the channel is holding on
   464	 *   its source side.
   465	 *
   466	 *   Needed at the end of a peripheral-sourced transfer: the last bytes of a
   467	 *   JPEG frame are unlikely to land on a 32-bit boundary, and without this
   468	 *   they sit in the channel and are counted as "not yet transferred", so the
   469	 *   frame looks short by up to three bytes.
   470	 *
   471	 *   Only bit[17] is written, never a read-modify-write, for the reason given
   472	 *   in the interrupt handler: the neighbouring interrupt bits are
   473	 *   write-1-to-clear.  The poll is bounded so this stays safe to call from
   474	 *   interrupt context.
   475	 *
   476	 ****************************************************************************/
   477	
   478	void bk7258_dma_flush_src_buffer(uint8_t channel)
   479	{
   480	  unsigned int spins;
   481	
   482	  if (channel >= BK7258_DMA_NCHANNELS)
   483	    {
   484	      return;
   485	    }
   486	
   487	  putreg32(BK7258_DMA_STATUS_FLUSH_SRC_BUFF,
   488	           BK7258_DMA_CH_STATUS(channel));
   489	
   490	  for (spins = 0; spins < BK7258_DMA_FLUSH_TIMEOUT; spins++)
   491	    {
   492	      if ((getreg32(BK7258_DMA_CH_STATUS(channel)) &
   493	           BK7258_DMA_STATUS_FLUSH_SRC_BUFF) == 0)
   494	        {
   495	          break;
   496	        }
   497	    }
   498	}

